-- Stage S11 GATE: read-only database checks for hosted Development. Generated by scripts/dev/hosted-executor/build-gate.cjs. NOT RUN against any hosted system.
-- Run once, as one statement, after stage S10 and BEFORE the containment end-state script. EVERY row must have ok = true. Any false row, any error, or any missing row keeps containment on.
-- Also required (cannot be expressed in SQL): the executor audit store shows a denied anon and authenticated role probe after every step; `verify` reports the final catalog fingerprint equal to the sealed one.
SELECT id, ok FROM (
  SELECT 'G01 containment still in force before S11: anon and authenticated have no USAGE on public'::text AS id, COALESCE((NOT has_schema_privilege('anon','public','USAGE') AND NOT has_schema_privilege('authenticated','public','USAGE')), false) AS ok
  UNION ALL
  SELECT 'G02 the ledger holds exactly the 28 executor rows'::text AS id, COALESCE(((SELECT count(*) FROM supabase_migrations.schema_migrations WHERE statements[1] LIKE '-- BPC-DEV-RECONCILIATION executed; executor=bpc-dev-executor/1;%') = 28), false) AS ok
  UNION ALL
  SELECT 'G03 orders has no policy for anon or public (SEC-001/002/003)'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='orders' AND roles && ARRAY['anon','public']::name[])), false) AS ok
  UNION ALL
  SELECT 'G04 no policy named like "service role" applies to public, anon or authenticated'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND policyname ILIKE '%service role%' AND roles && ARRAY['anon','public','authenticated']::name[])), false) AS ok
  UNION ALL
  SELECT 'G05 anon-executable public functions equal the accepted allow-list (SEC-010)'::text AS id, COALESCE(((SELECT coalesce(array_agg(DISTINCT p.proname::text ORDER BY p.proname::text), ARRAY[]::text[]) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prokind='f' AND has_function_privilege('anon', p.oid, 'EXECUTE')) = ARRAY['check_date_blackout','check_product_availability','check_unit_availability','get_public_business_settings','get_public_nav_menu_groups']::text[]), false) AS ok
  UNION ALL
  SELECT 'G06 anon table privileges equal the accepted allow-list (SEC-014/039)'::text AS id, COALESCE(((SELECT coalesce(array_agg(x ORDER BY x), ARRAY[]::text[]) FROM (SELECT c.relname||':'||p AS x FROM pg_class c, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p','v') AND has_table_privilege('anon', c.oid, p)) z) = ARRAY['google_reviews:SELECT','hero_carousel_images:SELECT','inventory_products:SELECT','package_inflatable_components:SELECT','package_inflatable_eligibility:SELECT','pending_signups_consent:INSERT','pricing_rules:SELECT','product_bundle_components:SELECT','product_bundle_excluded_categories:SELECT','product_bundles:SELECT','product_categories:SELECT','product_pricing:SELECT','unit_media:SELECT','units:SELECT']::text[]), false) AS ok
  UNION ALL
  SELECT 'G07 no sequence privilege for anon, no UPDATE for authenticated (SEC-014)'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace AND relkind='S' OFFSET 0) c WHERE has_sequence_privilege('anon', c.oid, 'USAGE') OR has_sequence_privilege('anon', c.oid, 'UPDATE') OR has_sequence_privilege('authenticated', c.oid, 'UPDATE'))), false) AS ok
  UNION ALL
  SELECT 'G08 row level security is on for every public table'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relkind IN ('r','p') AND NOT c.relrowsecurity)), false) AS ok
  UNION ALL
  SELECT 'G09 no SECURITY DEFINER function in public lacks a pinned search_path (SEC-037)'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prosecdef AND NOT EXISTS (SELECT 1 FROM unnest(coalesce(p.proconfig, ARRAY[]::text[])) c WHERE c LIKE 'search_path=%'))), false) AS ok
  UNION ALL
  SELECT 'G10 no default privilege entry in public or global names anon, authenticated or PUBLIC (SEC-015)'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_default_acl d, aclexplode(d.defaclacl) a WHERE (d.defaclnamespace = 0 OR d.defaclnamespace = 'public'::regnamespace) AND (a.grantee = 0 OR a.grantee IN (SELECT oid FROM pg_roles WHERE rolname IN ('anon','authenticated'))))), false) AS ok
  UNION ALL
  SELECT 'G11 public buckets are exactly the marketing buckets; every other bucket is private (SEC-018/019)'::text AS id, COALESCE(((SELECT coalesce(array_agg(id ORDER BY id), ARRAY[]::text[]) FROM storage.buckets WHERE public) = ARRAY['carousel-media','event-essentials-media','unit-images']::text[]), false) AS ok
  UNION ALL
  SELECT 'G12 no storage.objects policy grants INSERT, UPDATE, DELETE or ALL to anon or public (SEC-018)'::text AS id, COALESCE((NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND cmd IN ('INSERT','UPDATE','DELETE','ALL') AND roles && ARRAY['anon','public']::name[])), false) AS ok
  UNION ALL
  SELECT 'G13 the booking-confirmation guard trigger exists and is enabled on orders (SEC-047)'::text AS id, COALESCE((EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.orders'::regclass AND tgname='trg_guard_booking_confirmation_columns' AND tgenabled <> 'D')), false) AS ok
  UNION ALL
  SELECT 'G14 public schema ACL names only postgres and service_role'::text AS id, COALESCE(((SELECT coalesce(array_agg(g ORDER BY g), ARRAY[]::text[]) FROM (SELECT DISTINCT (CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END)::text AS g FROM pg_namespace n, aclexplode(n.nspacl) a WHERE n.nspname='public') z) = ARRAY['postgres','service_role']::text[]), false) AS ok
  UNION ALL
  SELECT 'G15 the signup trigger exists on auth.users (20261016120000)'::text AS id, COALESCE((EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='auth.users'::regclass AND tgname='on_auth_user_created' AND NOT tgisinternal)), false) AS ok
  UNION ALL
  SELECT 'G16 Step 3B 20261026120000: post_effect_present is true'::text AS id, COALESCE((SELECT (NOT EXISTS (SELECT 1 FROM (SELECT oid FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relkind = 'S' OFFSET 0) c WHERE has_sequence_privilege('anon', c.oid, 'USAGE') OR has_sequence_privilege('anon', c.oid, 'UPDATE') OR has_sequence_privilege('authenticated', c.oid, 'UPDATE')) AND NOT EXISTS (SELECT 1 FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p') AND has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') AND NOT EXISTS (SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = c.relname AND p.roles && ARRAY['anon','public']::name[]))) AS effect_present), false) AS ok
  UNION ALL
  SELECT 'G16 Step 3B 20261026120100: post_effect_present is true'::text AS id, COALESCE((SELECT NOT EXISTS (SELECT 1 FROM unnest(ARRAY['inventory_products','product_pricing','product_categories','product_bundles','product_bundle_components','package_inflatable_components','package_inflatable_eligibility','product_bundle_excluded_categories']) t WHERE to_regclass('public.' || t) IS NOT NULL AND NOT has_table_privilege('service_role', 'public.' || t, 'SELECT')) AS effect_present), false) AS ok
  UNION ALL
  SELECT 'G16 Step 3B 20261026120200: post_effect_present is true'::text AS id, COALESCE((SELECT (EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'task_status' AND policyname = 'Crew create task status' AND cmd = 'INSERT') AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'transaction_receipts' AND policyname = 'Admin and master update transaction receipts' AND cmd = 'UPDATE')) AS effect_present), false) AS ok
  UNION ALL
  SELECT 'G16 Step 3B 20261026120300: post_effect_present is true'::text AS id, COALESCE((SELECT (EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.orders'::regclass AND tgname = 'trg_guard_booking_confirmation_columns' AND NOT tgisinternal AND tgenabled = 'O') AND NOT has_function_privilege('anon', 'public.guard_booking_confirmation_columns()', 'EXECUTE') AND NOT has_function_privilege('authenticated', 'public.guard_booking_confirmation_columns()', 'EXECUTE')) AS effect_present), false) AS ok
  UNION ALL
  SELECT 'G16 Step 3B 20261026120400: post_effect_present is true'::text AS id, COALESCE((SELECT NOT EXISTS (SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE d.defaclnamespace = 'public'::regnamespace AND pg_get_userbyid(d.defaclrole) IN ('supabase_admin', 'postgres') AND (a.grantee = 0 OR pg_get_userbyid(a.grantee) IN ('anon', 'authenticated'))) AS effect_present), false) AS ok
) g ORDER BY id;
